// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }
    function testFuzz_property(uint256 credChainId, uint256 credId, string calldata verificationType) public {
        // Admissible domain: non-zero chain id and cred id, non-empty verification type
        vm.assume(credChainId > 0);
        vm.assume(credId > 0);
        vm.assume(bytes(verificationType).length > 0);

        // Initialize the contract (this sets the owner to msg.sender via __Ownable_init)
        address initialOwner = address(this);
        c.initialize(credChainId, credId, verificationType, address(this));

        // The invariant: the owner should be the initial owner (non-zero after initialization)
        address currentOwner = c.owner();
        assertTrue(currentOwner != address(0));
    }
}

