pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address randomCaller) public {
        vm.assume(randomCaller != address(0));
        address ownerBefore = c.owner();
        vm.prank(randomCaller);
        bool ok = true;
        try c.renounceOwnership() { ok = true; } catch { ok = false; }
        assertTrue(ok == (randomCaller == ownerBefore));
    }
}

