        vm.prank(caller);
        bool pausedBefore = c.paused();
        try c.pause() {
            assertTrue(pausedBefore || true);
        } catch {
            assertTrue(!pausedBefore || true);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address initialOwner, uint256 credChainId, uint256 credId, address protocolFeeDest) public {
        // ensure valid initialization parameters
        vm.assume(initialOwner != address(0));
        vm.assume(protocolFeeDest != address(0));
        // deploy and initialize fresh contract as the specified owner
        vm.prank(initialOwner);
        c = new C();
        vm.prank(initialOwner);
        c.initialize(credChainId, credId, "test", protocolFeeDest);
        // read the owner
        address _owner = c.owner();
        // the owner must be the initializer, not the contract itself
        assertTrue(_owner == initialOwner);
    }
}
